select store_sales.store_id, store_sales.product_id, round(stddev(inventory.quantity), 2) stddev_quantity from inventory join store_sales on inventory.store_id = store_sales.store_id and inventory.product_id = store_sales.product_id where store_sales.product_id = 10 group by store_sales.store_id, store_sales.product_id having round(stddev(inventory.quantity), 2) > 61 order by product_id desc, store_sales.store_id desc
